// Vulnerable: reads a single oracle's current price
// with no check on how much liquidity backs it, or
// how recently/sharply it moved.
function getPositionValue(address trader)
    public view returns (uint256)
{
    uint256 price = priceOracle.getPrice(MNGO_USDC_PAIR);
    return positions[trader].size * price;
}

// Safer: check a spot price against a slower
// reference before trusting a large, sudden move.
function getPositionValueSafer(address trader)
    public view returns (uint256)
{
    uint256 spot = priceOracle.getPrice(MNGO_USDC_PAIR);
    uint256 ref = twapOracle.consult(MNGO_USDC_PAIR, 1 hours);
    uint256 dev = spot > ref
        ? ((spot - ref) * 100) / ref
        : ((ref - spot) * 100) / ref;
    require(dev <= MAX_ALLOWED_DEVIATION_PERCENT);
    return positions[trader].size * spot;
}
